package sfz.shard.l01.demo

import java.util.Random

/** A payment on virtual time: milliseconds since midnight, no clock involved. */
data class Pay(val id: String, val merchant: String, val atMillis: Long)

fun payments(count: Int, startMillis: Long, everyMillis: Long, firstId: Int, seed: Long): List<Pay> {
    val rnd = Random(seed)
    return (0 until count).map { i -> Pay("pay-${firstId + i}", "M-%04d".format(rnd.nextInt(500)), startMillis + i * everyMillis) }
}

fun hours(h: Int, m: Int = 0) = (h * 60L + m) * 60_000L

/** Key-range shards: sorted split points; a key belongs to the shard after the last boundary <= key. */
class Ranges(val boundaries: List<String>) {
    fun shardOf(key: String) = boundaries.count { it <= key }

    companion object {
        // cut a sample into equal runs, so the shards follow the data
        fun fromSample(keys: List<String>, n: Int) = keys.sorted().let { s -> Ranges((1 until n).map { s[it * s.size / n] }) }
    }
}

/** Eight range shards cut from the morning's keys. Then the afternoon arrives. Where do the inserts go? */
fun main() {
    val morning = payments(20_000, startMillis = hours(8), everyMillis = 1_000, firstId = 0, seed = 7)
    val afternoon = payments(10_000, startMillis = hours(14), everyMillis = 5, firstId = 20_000, seed = 8)
    val day = morning + afternoon

    val byTime = { p: Pay -> "%013d#%s".format(p.atMillis, p.id) }
    val byMerchant = { p: Pay -> "%s#%013d#%s".format(p.merchant, p.atMillis, p.id) }

    for ((name, key) in listOf("time first" to byTime, "merchant first" to byMerchant)) {
        val shards = Ranges.fromSample(morning.map(key), 8)
        val inserts = IntArray(8).also { c -> afternoon.forEach { c[shards.shardOf(key(it))]++ } }
        // which shards would a query have to ask? the ones that hold at least one matching payment
        fun shardsHolding(match: (Pay) -> Boolean) = day.filter(match).map { shards.shardOf(key(it)) }.toSortedSet()
        println("key = $name, for example ${key(afternoon[0])}")
        println("  afternoon inserts per shard: ${inserts.toList()}")
        println("  shards holding 14:00 to 14:05:  ${shardsHolding { it.atMillis in hours(14) until hours(14, 5) }}")
        println("  shards holding M-0042's day:    ${shardsHolding { it.merchant == "M-0042" }}")
    }
}

package sfz.shard.l01.demo

import java.nio.ByteBuffer
import java.security.MessageDigest
import java.util.Random

/** The first 8 bytes of MD5: the same number in every process, and neighbouring keys land far apart. */
fun md5(key: String): Long = ByteBuffer.wrap(MessageDigest.getInstance("MD5").digest(key.toByteArray())).long

/** Hash sharding: shard = hash mod 8. Same payments as the range demo, plus a Black Friday afternoon. */
fun main() {
    val shardOf = { key: String -> Math.floorMod(md5(key), 8L).toInt() }
    val afternoon = payments(10_000, startMillis = hours(14), everyMillis = 5, firstId = 20_000, seed = 8)
    // Black Friday: the same afternoon, but M-0042 takes every fifth payment
    val blackFriday = afternoon.mapIndexed { i, p -> if (i % 5 == 0) p.copy(merchant = "M-0042") else p }

    val byTime = { p: Pay -> "%013d#%s".format(p.atMillis, p.id) }
    val byMerchant = { p: Pay -> p.merchant } // the partition key alone; rows sort by time inside it

    for ((name, key) in listOf("time + id" to byTime, "merchant" to byMerchant)) {
        fun inserts(day: List<Pay>) = IntArray(8).also { c -> day.forEach { c[shardOf(key(it))]++ } }.toList()
        fun shardsHolding(match: (Pay) -> Boolean) = blackFriday.filter(match).map { shardOf(key(it)) }.toSortedSet()
        println("partition key = $name")
        println("  normal afternoon, inserts per shard: ${inserts(afternoon)}")
        println("  Black Friday,     inserts per shard: ${inserts(blackFriday)}")
        println("  shards holding 14:00 to 14:05:  ${shardsHolding { it.atMillis in hours(14) until hours(14, 5) }}")
        println("  shards holding M-0042's day:    ${shardsHolding { it.merchant == "M-0042" }}")
    }
    println("String.hashCode() of pay-1, pay-2, pay-3: ${listOf("pay-1", "pay-2", "pay-3").map { it.hashCode() }}")
}

package sfz.shard.l01.demo

/** 1,000 merchants on 10 cells. Sizes follow a Zipf curve: the k-th biggest sends 1/k as much as the biggest. */
fun main() {
    val total = 20_000.0 // payments a second, all merchants together
    val harmonic = (1..1_000).sumOf { 1.0 / it }
    val merchants = (1..1_000).associate { k -> "T-%04d".format(k) to total / (k * harmonic) }
    val cells = 10

    // the thin router's rule: hash the tenant id mod the cell count
    val byHash = merchants.keys.associateWith { Math.floorMod(md5(it), cells.toLong()).toInt() }

    // size-aware: tenants over 2,000 a second get a cell alone; the rest go biggest first to the emptiest shared cell
    val bySize = LinkedHashMap<String, Int>()
    val loads = DoubleArray(cells)
    var nextDedicated = 0
    for ((id, rate) in merchants.entries.sortedByDescending { it.value }) {
        val cell = if (rate >= 2_000.0) nextDedicated++ else (nextDedicated until cells).minBy { loads[it] }
        bySize[id] = cell
        loads[cell] += rate
    }

    println("T-0001 alone sends %.0f payments a second, %.1f%% of all".format(merchants.getValue("T-0001"), merchants.getValue("T-0001") / total * 100))
    for ((name, placement) in listOf("hash of tenant id" to byHash, "size-aware" to bySize)) {
        val perCell = DoubleArray(cells).also { l -> placement.forEach { (id, c) -> l[c] += merchants.getValue(id) } }
        val home = placement.getValue("T-0001")
        val neighbours = placement.count { (id, c) -> c == home && id != "T-0001" }
        println(name)
        println("  payments a second per cell: ${perCell.map { "%.0f".format(it) }}")
        println("  T-0001 is in cell $home with $neighbours other merchants")
        println("  a bad deploy to cell $home hits %.1f%% of payments; to the quietest cell, %.1f%%"
            .format(perCell[home] / total * 100, perCell.min() / total * 100))
    }
}

