fun rangeShard(boundaries: List<String>, key: String): Int {
    var lo = 0
    var hi = boundaries.size
    while (lo < hi) {
        val mid = (lo + hi) ushr 1
        if (boundaries[mid] <= key) lo = mid + 1 else hi = mid // equal goes right
    }
    return lo // the number of boundaries <= key
}

fun hashShard(key: String, shards: Int): Int =
    Math.floorMod(stableHash(key), shards.toLong()).toInt() // stable across JVMs, never negative

